example.code:
secret = 7
guess = int(input())
# 같은 경우(정답)를 가장 먼저 확인하고, 나머지 경우를 나눠요.
if guess == secret:
    print("정답!")
elif guess > secret:
    print("더 작은 수예요")
else:
    print("더 큰 수예요")

